import os
import re
from datetime import datetime
from typing import Dict, Any, List, Optional, Tuple

DEFAULT_RULE_FILE = ".llmrules"

FORMAT_MARKDOWN = "markdown"
FORMAT_TOON = "toon"
FORMAT_TYPESCRIPT = "ts"
FORMAT_YAML = "yaml"

MARKDOWN_TEMPLATE = """# 🧠 GitContext: AI Architecture Memory
# AUTOGENERATED & CONTINUOUSLY SYNCED FROM GIT COMMITS.
# Feed this file to Cursor, Copilot, Claude Code, or Antigravity for instant codebase context.

## 🛠️ Tech Stack & Conventions
{conventions}

## 📐 Architecture & Coding Rules
{rules}

## 🚫 Deprecations & Anti-Patterns
{deprecations}

## 📜 Recent Architectural Changes
{recent_history}

---
*Maintained automatically by [GitContext](https://github.com/oneorbit/git-context) by [OneOrbit](https://oneorbit.dev) — Living context for AI pair programming.*
"""

TOON_HEADER = """# @GITCONTEXT:TOON:v1 by OneOrbit (https://oneorbit.dev)
# Token-dense living architecture memory for LLM context optimization.
"""

TYPESCRIPT_HEADER = """/**
 * 🧠 GitContext: AI Codebase Architecture Definitions
 * Generated by GitContext by OneOrbit (https://oneorbit.dev)
 * Type-level constraints for Cursor, Copilot, and Claude Code.
 */
"""

def estimate_tokens(text: str) -> int:
    """
    Approximates BPE token counts (cl100k/o200k/SentencePiece) without external dependencies.
    Accurately accounts for words, symbols, whitespace, and code syntax.
    """
    if not text:
        return 0
    tokens = re.findall(r'[a-zA-Z0-9]+|[^a-zA-Z0-9\s]|\n', text)
    count = 0
    for t in tokens:
        if t == '\n':
            count += 1
        elif len(t) <= 4:
            count += 1
        else:
            count += max(1, (len(t) + 2) // 4)
    return max(1, count)

class MemoryStore:
    """
    Manages reading, updating, and formatting codebase context rules.
    Supports multiple LLM-optimized formats:
    - markdown: Standard human-readable markdown (.llmrules / PROJECT_MEMORY.md)
    - toon: Token-Oriented Object Notation (50-70% token savings)
    - ts: TypeScript architectural definition DSL (.d.ts) (high adherence, 40-50% savings)
    - yaml: Compact key-value flow YAML (40% savings)
    """

    @staticmethod
    def estimate_tokens(text: str) -> int:
        return estimate_tokens(text)

    def __init__(self, repo_path: str = ".", filename: str = DEFAULT_RULE_FILE, format_type: str = "auto"):
        self.repo_path = os.path.abspath(repo_path)
        self.filename = filename
        self.file_path = os.path.join(self.repo_path, filename)
        self.format_type = self._resolve_format(format_type)

    def _resolve_format(self, requested_format: str) -> str:
        if requested_format and requested_format != "auto":
            req = requested_format.lower()
            if req in ["ts", "typescript", "dts"]:
                return FORMAT_TYPESCRIPT
            elif req in ["toon", "dense"]:
                return FORMAT_TOON
            elif req in ["yaml", "yml"]:
                return FORMAT_YAML
            return FORMAT_MARKDOWN

        # Auto-detect from filename extension
        lower_name = self.filename.lower()
        if lower_name.endswith(".toon"):
            return FORMAT_TOON
        elif lower_name.endswith(".d.ts") or lower_name.endswith(".ts"):
            return FORMAT_TYPESCRIPT
        elif lower_name.endswith(".yaml") or lower_name.endswith(".yml"):
            return FORMAT_YAML

        # Inspect file content if it already exists
        if os.path.isfile(self.file_path):
            try:
                with open(self.file_path, "r", encoding="utf-8") as f:
                    preview = f.read(512)
                if "@GITCONTEXT:TOON" in preview or "@CONV:" in preview:
                    return FORMAT_TOON
                elif "export interface" in preview or "export namespace" in preview:
                    return FORMAT_TYPESCRIPT
                elif preview.startswith("conventions:") or "\nconventions:" in preview:
                    return FORMAT_YAML
            except Exception:
                pass

        return FORMAT_MARKDOWN

    def exists(self) -> bool:
        return os.path.isfile(self.file_path)

    def load(self) -> Dict[str, Any]:
        """Parses existing rule file into structured sections regardless of format."""
        empty_state = {
            "conventions": [],
            "rules": [],
            "deprecations": [],
            "history": []
        }
        if not self.exists():
            return empty_state

        try:
            with open(self.file_path, "r", encoding="utf-8") as f:
                content = f.read()
        except Exception:
            return empty_state

        detected = self.format_type
        if "@GITCONTEXT:TOON" in content or "@CONV:" in content:
            return self._load_toon(content)
        elif "export interface" in content or "export namespace" in content:
            return self._load_typescript(content)
        elif "conventions:" in content and "rules:" in content:
            return self._load_yaml(content)
        else:
            return self._load_markdown(content)

    def _load_markdown(self, content: str) -> Dict[str, Any]:
        conventions = self._extract_md_section(content, "🛠️ Tech Stack & Conventions")
        rules = self._extract_md_section(content, "📐 Architecture & Coding Rules")
        deprecations = self._extract_md_section(content, "🚫 Deprecations & Anti-Patterns")
        history = self._extract_md_section(content, "📜 Recent Architectural Changes")
        return {
            "conventions": conventions,
            "rules": rules,
            "deprecations": [d for d in deprecations if d != "None documented."],
            "history": history
        }

    def _extract_md_section(self, content: str, title: str) -> List[str]:
        pattern = rf'## {re.escape(title)}\n(.*?)(?=\n## |\n---\n|$)'
        match = re.search(pattern, content, re.DOTALL)
        if not match:
            return []
        lines = match.group(1).strip().split("\n")
        items = []
        for l in lines:
            l_clean = l.strip()
            if l_clean.startswith("- "):
                items.append(l_clean[2:].strip())
            elif l_clean and not l_clean.startswith("#"):
                items.append(l_clean)
        return items

    def _load_toon(self, content: str) -> Dict[str, Any]:
        conventions, rules, deprecations, history = [], [], [], []
        for line in content.splitlines():
            line = line.strip()
            if line.startswith("@CONV:"):
                items = line[len("@CONV:"):].split("|")
                conventions.extend([i.strip() for i in items if i.strip()])
            elif line.startswith("@RULE:"):
                items = line[len("@RULE:"):].split("|")
                rules.extend([i.strip() for i in items if i.strip()])
            elif line.startswith("@DEPR:"):
                items = line[len("@DEPR:"):].split("|")
                deprecations.extend([i.strip() for i in items if i.strip() and i.strip() != "None"])
            elif line.startswith("@HIST:"):
                items = line[len("@HIST:"):].split("|")
                history.extend([i.strip() for i in items if i.strip()])

        return {
            "conventions": list(dict.fromkeys(conventions)),
            "rules": list(dict.fromkeys(rules)),
            "deprecations": list(dict.fromkeys(deprecations)),
            "history": list(dict.fromkeys(history))
        }

    def _load_typescript(self, content: str) -> Dict[str, Any]:
        def extract_array(key: str) -> List[str]:
            pattern = rf'readonly\s+{key}:\s*\[(.*?)\];'
            match = re.search(pattern, content, re.DOTALL)
            if not match:
                return []
            block = match.group(1)
            raw = re.findall(r'"([^"\\]*(?:\\.[^"\\]*)*)"', block)
            return [s.replace('\\"', '"').strip() for s in raw if s.strip() and s.strip() != "None documented"]

        return {
            "conventions": extract_array("conventions"),
            "rules": extract_array("rules"),
            "deprecations": extract_array("deprecations"),
            "history": extract_array("recentHistory")
        }

    def _load_yaml(self, content: str) -> Dict[str, Any]:
        def extract_yaml_items(key: str) -> List[str]:
            pattern = rf'^{key}:\s*\n((?:\s*-\s*.*?\n)*)'
            match = re.search(pattern, content, re.MULTILINE)
            if not match:
                return []
            items = []
            for l in match.group(1).splitlines():
                l = l.strip()
                if l.startswith("- "):
                    val = l[2:].strip().strip('"\'')
                    if val and val != "None documented":
                        items.append(val)
            return items

        return {
            "conventions": extract_yaml_items("conventions"),
            "rules": extract_yaml_items("rules"),
            "deprecations": extract_yaml_items("deprecations"),
            "history": extract_yaml_items("recentHistory")
        }

    def format_content(self, data: Dict[str, Any], format_type: Optional[str] = None) -> str:
        """Formats the structured data into the specified format string."""
        fmt = format_type or self.format_type
        conventions = data.get("conventions", [])
        rules = data.get("rules", [])
        deprecations = data.get("deprecations", [])
        history = data.get("history", [])

        if fmt == FORMAT_TOON:
            lines = [TOON_HEADER.strip()]
            if conventions:
                clean_conv = [c.replace("|", "/") for c in conventions]
                lines.append(f"@CONV:{'|'.join(clean_conv)}")
            if rules:
                clean_rules = [r.replace("|", "/") for r in rules]
                lines.append(f"@RULE:{'|'.join(clean_rules)}")
            if deprecations:
                clean_depr = [d.replace("|", "/") for d in deprecations]
                lines.append(f"@DEPR:{'|'.join(clean_depr)}")
            if history:
                clean_hist = [h.replace("|", "/") for h in history]
                lines.append(f"@HIST:{'|'.join(clean_hist)}")
            return "\n".join(lines) + "\n"

        elif fmt == FORMAT_TYPESCRIPT:
            def to_ts_array(items: List[str]) -> str:
                if not items:
                    return "    // none"
                lines = []
                for item in items:
                    escaped = item.replace('"', '\\"')
                    lines.append(f'    "{escaped}",')
                return "\n".join(lines)

            depr_items = deprecations if deprecations else ["None documented"]
            ts_code = f"""{TYPESCRIPT_HEADER.strip()}
export interface CodebaseMemory {{
  readonly conventions: [
{to_ts_array(conventions)}
  ];
  readonly rules: [
{to_ts_array(rules)}
  ];
  readonly deprecations: [
{to_ts_array(depr_items)}
  ];
  readonly recentHistory: [
{to_ts_array(history)}
  ];
}}
"""
            return ts_code

        elif fmt == FORMAT_YAML:
            lines = [
                "# 🧠 GitContext Architecture Memory",
                "# Generated by GitContext by OneOrbit (https://oneorbit.dev)",
                "conventions:"
            ]
            if conventions:
                for c in conventions:
                    escaped = c.replace('"', '\\"')
                    lines.append(f'  - "{escaped}"')
            else:
                lines.append('  - "Standard conventions apply"')

            lines.append("rules:")
            if rules:
                for r in rules:
                    escaped = r.replace('"', '\\"')
                    lines.append(f'  - "{escaped}"')
            else:
                lines.append('  - "Follow established patterns"')

            lines.append("deprecations:")
            if deprecations:
                for d in deprecations:
                    escaped = d.replace('"', '\\"')
                    lines.append(f'  - "{escaped}"')
            else:
                lines.append('  - "None documented"')

            lines.append("recentHistory:")
            if history:
                for h in history:
                    escaped = h.replace('"', '\\"')
                    lines.append(f'  - "{escaped}"')
            else:
                lines.append('  - "Initial baseline"')

            return "\n".join(lines) + "\n"

        else:
            # Markdown default
            conventions_md = "\n".join([f"- {c}" for c in conventions]) if conventions else "- Standard modern development conventions apply."
            rules_md = "\n".join([f"- {r}" for r in rules]) if rules else "- Follow existing module structure and patterns."
            deprecations_md = "\n".join([f"- {d}" for d in deprecations]) if deprecations else "- None documented."
            history_md = "\n".join([f"- {h}" for h in history]) if history else "- Initial context baseline generated."

            return MARKDOWN_TEMPLATE.format(
                conventions=conventions_md,
                rules=rules_md,
                deprecations=deprecations_md,
                recent_history=history_md
            )

    def get_token_benchmark(self, data: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Calculates token counts across all supported formats for comparison."""
        active_data = data or self.load()
        md_text = self.format_content(active_data, FORMAT_MARKDOWN)
        toon_text = self.format_content(active_data, FORMAT_TOON)
        ts_text = self.format_content(active_data, FORMAT_TYPESCRIPT)
        yaml_text = self.format_content(active_data, FORMAT_YAML)

        md_tokens = estimate_tokens(md_text)
        toon_tokens = estimate_tokens(toon_text)
        ts_tokens = estimate_tokens(ts_text)
        yaml_tokens = estimate_tokens(yaml_text)

        toon_savings = max(0, round((1.0 - (toon_tokens / max(1, md_tokens))) * 100))
        ts_savings = max(0, round((1.0 - (ts_tokens / max(1, md_tokens))) * 100))
        yaml_savings = max(0, round((1.0 - (yaml_tokens / max(1, md_tokens))) * 100))

        return {
            "markdown": {"tokens": md_tokens, "savings_pct": 0},
            "toon": {"tokens": toon_tokens, "savings_pct": toon_savings},
            "ts": {"tokens": ts_tokens, "savings_pct": ts_savings},
            "yaml": {"tokens": yaml_tokens, "savings_pct": yaml_savings}
        }

    def update(
        self,
        new_rules: List[str],
        new_conventions: List[str],
        new_deprecations: List[str],
        commit_entry: Optional[Dict[str, Any]] = None,
        max_history: int = 5
    ) -> str:
        """Appends new architectural directives and keeps rule file within token limits."""
        current = self.load()

        merged_conventions = list(dict.fromkeys(current["conventions"] + new_conventions))
        merged_rules = list(dict.fromkeys(current["rules"] + new_rules))
        merged_deprecations = list(dict.fromkeys(current["deprecations"] + new_deprecations))

        history = current["history"]
        if commit_entry:
            short_h = commit_entry.get("short_hash", "")
            subject = commit_entry.get("subject", "")
            summary = commit_entry.get("summary", subject)
            date_str = datetime.utcnow().strftime("%Y-%m-%d")
            history_item = f"[{short_h}] ({date_str}) {summary}"
            if history_item not in history:
                history.insert(0, history_item)

        history = history[:max_history]

        data = {
            "conventions": merged_conventions,
            "rules": merged_rules,
            "deprecations": merged_deprecations,
            "history": history
        }

        new_content = self.format_content(data, self.format_type)

        with open(self.file_path, "w", encoding="utf-8") as f:
            f.write(new_content)

        return new_content
